// Learning Hub courseware: six ENTC tracks of short lessons. Each lesson explains one idea in
// plain English, lists the key formulas, links to the lab where it can be tried, and ends with
// a quiz (multiple choice plus numeric questions with fresh numbers on every attempt). Every
// track also has a viva-voce question bank.

const mcq = (id, prompt, options, answer, explain) => ({ type: 'mcq', id, prompt, options, answer, explain });
const num = (id, params, prompt, answer, unit, explain, tolerance = 0.02) => ({ type: 'numeric', id, params, prompt, answer, unit, explain, tolerance });
const E = (value, unit = '') => { const p = [[1e9, 'G'], [1e6, 'M'], [1e3, 'k'], [1, ''], [1e-3, 'm'], [1e-6, 'µ'], [1e-9, 'n'], [1e-12, 'p']]; const [s, x] = p.find(([v]) => Math.abs(value) >= v * 0.9999) ?? p.at(-1); return `${Number((value / s).toPrecision(4))} ${x}${unit}`; };

