        formulas: ['FIR: y[n] = Σ b_k·x[n − k]', 'IIR: y[n] = Σ b_k·x[n − k] − Σ a_k·y[n − k]', 'Butterworth roll-off: 20·N dB/decade', 'Linear-phase FIR delay = (N − 1)/2 samples'],
